create function pg_temp.alm_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'ALM FAIL: %',label;end if;raise notice 'ALM PASS: %',label;end$$;
create function pg_temp.alm_reject(q text,code text,label text) returns void language plpgsql as $$begin begin execute q;exception when others then if sqlstate=code then raise notice 'ALM PASS: %',label;return;end if;raise exception 'ALM FAIL: % expected %, got %: %',label,code,sqlstate,sqlerrm;end;raise exception 'ALM FAIL: % accepted',label;end$$;
